"""ST declaration coverage (generated by tools/gen_lang_tests.py - do not edit by hand)."""

import unittest

from stc.compiler import compile_source


class DeclsTests(unittest.TestCase):

    def test_001_in_out_params(self):
        source = """\
FUNCTION B01Io : INT
VAR_INPUT A : INT; END_VAR
VAR_OUTPUT B : INT; END_VAR
VAR_IN_OUT C : INT; END_VAR
B := A;
C := C + 1;
B01Io := B + C;
END_FUNCTION
"""
        c_result = compile_source(source, "c", standard="ed3")
        self.assertTrue(c_result.success, c_result.diagnostics or c_result.syntax_error)
        self.assertIn('int16_t B01Io(', c_result.output)
        rust_result = compile_source(source, "rust", standard="ed3")
        self.assertTrue(rust_result.success, rust_result.diagnostics or rust_result.syntax_error)
        self.assertIn('pub fn B01Io(', rust_result.output)

    def test_002_retain_program(self):
        source = """\
PROGRAM B02Ret
VAR RETAIN Saved : DINT := 10; END_VAR
Saved := Saved + 1;
END_PROGRAM
"""
        c_result = compile_source(source, "c", standard="ed3")
        self.assertTrue(c_result.success, c_result.diagnostics or c_result.syntax_error)
        self.assertIn('void B02Ret_cold_init', c_result.output)
        self.assertIn('void B02Ret_run', c_result.output)
        rust_result = compile_source(source, "rust", standard="ed3")
        self.assertTrue(rust_result.success, rust_result.diagnostics or rust_result.syntax_error)
        self.assertIn('pub struct B02Ret', rust_result.output)
        self.assertIn('cold_init', rust_result.output)

